        slides: [{"page": 120, "heading": "4.15 Scaling Agents", "bullets": ["for Production", "Environments"]}, {"page": 121, "heading": "\u25cf Horizontal Scaling: Most components can be scaled horizontally since", "bullets": ["core agent operations are I/O bound", "\u25cf Statelessness: Externalize all state so any worker can handle any", "request"]}, {"page": 122, "heading": "\u25cf Vertical Scaling (Scale Up)", "bullets": ["\u25cb Add more power to existing machines (CPU, RAM, disk)", "\u25cb Simpler to implement since no distributed coordination needed", "\u25cb Hard ceiling: eventually you hit hardware limits"]}, {"page": 123, "heading": "\u25cf The Nature of Agent Workloads", "bullets": ["\u25cb High Latency: LLM inference and tool execution take seconds to minutes.", "\u25cb Blocking Operations: A single fast CPU cannot force an LLM to generate tokens faster.", "\u25cb The Solution: You don't need a faster machine; you need more machines running in parallel."]}, {"page": 124, "heading": "\u25cf Statelessness: Workers store no data locally; they fetch context from a DB, act,", "bullets": ["and save it back.", "\u25cf The Constraint: Agents accumulate massive state (history, tool outputs) unlike", "simple web requests."]}, {"page": 125, "heading": "\u25cf Mechanism: A reverse proxy that distributes incoming requests across a pool of", "bullets": ["available servers.", "\u25cf Scalability Contribution: Decouples clients from specific servers, allowing addition", "or removal backend nodes dynamically."]}, {"page": 126, "heading": "\u25cf Mechanism: An asynchronous buffer where tasks wait until a worker is available", "bullets": ["to process them.", "\u25cf Decoupling: Separates rapid user input from slow, expensive agent execution.", "\u25cf Backpressure: Absorbs traffic spikes so workers don't crash from overload."]}, {"page": 127, "heading": "\u25cf Hot Storage (Redis): Ephemeral context/history. Cluster mode required for horizontal", "bullets": ["scale.", "\u25cf Warm Storage (SQL/NoSQL): Durable user data. Offload heavy reads to Replicas.", "\u25cf Cold Storage (S3): Offload large artifacts (images, PDFs) to keep DBs lean."]}, {"page": 128, "heading": "\u25cf The Risk: LLM costs scale linearly; one runaway loop can drain budgets instantly.", "bullets": ["\u25cf Token Budgets: Enforce hard caps per tenant/user per time window (e.g., $10/day).", "\u25cf Concurrency Limits: Restrict parallel tasks per tenant to prevent resource", "monopolization."]}, {"page": 129, "heading": "Example: Scaled Architecture", "bullets": []}, {"page": 130, "heading": "\u25cf Assume Failure: LLMs time out, tools break. Design for automatic retries.", "bullets": ["\u25cf Graceful Shutdowns: Nodes must finish current tasks before terminating (don't kill", "\"thinking\" agents).", "\u25cf Scale on Metrics: Monitor queue latency and token burn rate, not just CPU."]}]
