// Helper lookup functions
export function getAllModules(): CourseModule[] {
  return COURSE_LEVELS.flatMap(l => l.modules);
}

export function getModuleById(id: string): CourseModule | undefined {
  return getAllModules().find(m => m.id === id);
}

export function getLevelById(id: string): CourseLevel | undefined {
  return COURSE_LEVELS.find(l => l.id === id);
}